-- Perfiles olfativos de los perfumes publicados (09/10/2026).
-- Fuente de cada perfil en source_url: la ficha del distribuidor oficial en
-- España (orientfragance.com, la misma de su PVP) o la web de la marca. Las
-- notas son las que da la fuente, como claves de src/modules/catalog/domain/
-- scent.ts; familias, estación y momento del día solo cuando la fuente los
-- indica (etiquetas de la tienda, «Familia olfativa» o «Época del año
-- recomendada»). Sin fuente no hay perfil: Pharaoh Ramesses II, Game of Spades
-- Blind Bid y Yara Aceite Concentrado quedan sin él. Idempotente.
insert into public.product_scent_profiles
  (product_id, top_notes, heart_notes, base_notes, key_notes, families, seasons, times_of_day, source_url, source_note)
select p.id, v.top_notes::text[], v.heart_notes::text[], v.base_notes::text[], v.key_notes::text[],
  v.families::text[], v.seasons::text[], v.times_of_day::text[], v.source_url, v.source_note
