join public.products p on p.slug = v.slug
on conflict (product_id) do update set
  top_notes = excluded.top_notes, heart_notes = excluded.heart_notes,
  base_notes = excluded.base_notes, key_notes = excluded.key_notes,
  families = excluded.families, seasons = excluded.seasons,
  times_of_day = excluded.times_of_day, source_url = excluded.source_url,
  source_note = excluded.source_note;
